<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\FuelRecord; use Illuminate\Http\Request;
class FuelRecordController extends Controller { public function index(Request $request){$q=FuelRecord::with(['vehicle','driver'])->where('is_deleted',false); if($request->filled('search')){$s=$request->search;$q->where(fn($x)=>$x->where('record_no','like',"%$s%")->orWhere('station_name','like',"%$s%"));} return response()->json(['success'=>true,'data'=>$q->latest('fuel_date')->paginate($request->integer('per_page',15))]);} public function store(Request $r){return response()->json(['success'=>true,'data'=>FuelRecord::create($this->data($r)+['record_no'=>'FUEL-'.now()->format('Y').'-'.str_pad(FuelRecord::count()+1,4,'0',STR_PAD_LEFT)])],201);} public function update(Request $r,FuelRecord $fuelRecord){$fuelRecord->update($this->data($r));return response()->json(['success'=>true,'data'=>$fuelRecord]);} public function destroy(FuelRecord $fuelRecord){$fuelRecord->update(['is_deleted'=>true]);return response()->json(['success'=>true]);} private function data(Request $r){return $r->validate(['vehicle_id'=>'required|exists:vehicles,id','driver_id'=>'nullable|exists:drivers,id','fuel_date'=>'required|date','fuel_type'=>'required|string|max:50','uom'=>'nullable|string|max:20','quantity'=>'required|numeric|min:0.01','unit_price'=>'required|numeric|min:0','total_cost'=>'required|numeric|min:0','odometer_km'=>'nullable|integer|min:0','station_name'=>'nullable|string|max:150','payment_method'=>'nullable|string|max:50','receipt_path'=>'nullable|string|max:255','notes'=>'nullable|string']);} }
